import { migrate as migratePglite } from "drizzle-orm/pglite/migrator";
import {
  migrate as migratePostgres,
} from "drizzle-orm/postgres-js/migrator";
import type { PgliteDatabase } from "drizzle-orm/pglite";
import type { PostgresJsDatabase } from "drizzle-orm/postgres-js";
import { fileURLToPath } from "node:url";
import { getDb, getDbKind } from "./client";
import type * as schema from "./schema";

/**
 * Applies the migrations in ./drizzle (generated by `npm run db:generate`)
 * to the configured database:
 *
 *   npm run db:migrate              # PGlite local database (default)
 *   DATABASE_URL=postgres://... npm run db:migrate  # Postgres server
 *
 * Also invoked programmatically at server startup in a future slice.
 */
export async function runMigrations(): Promise<void> {
  const db = getDb();

  if (getDbKind() === "pglite") {
    await migratePglite(db as PgliteDatabase<typeof schema>, {
      migrationsFolder: "./drizzle",
    });
  } else {
    await migratePostgres(db as PostgresJsDatabase<typeof schema>, {
      migrationsFolder: "./drizzle",
    });
  }
}

const isDirectRun =
  process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];

if (isDirectRun) {
  runMigrations()
    .then(() => {
      console.log("Migrations applied.");
      process.exit(0);
    })
    .catch((error) => {
      console.error("Migration failed:", error);
      process.exit(1);
    });
}
